#!/usr/bin/env python3
from pathlib import Path
import base64, gzip, subprocess, tempfile

root = Path("FushERP_Mobile_Phase5")
if not root.is_dir():
    raise SystemExit("FushERP_Mobile_Phase5 source directory not found")
gradle = (root / "app/build.gradle.kts").read_text(encoding="utf-8")
db = (root / "app/src/main/java/com/fush/erp/data/FushDatabase.kt").read_text(encoding="utf-8")
if "versionCode = 45" not in gradle or "0.15.4.6-phase14.5-inventory-warehouse-separation" not in gradle:
    raise SystemExit("Phase 14.5.6 source baseline mismatch")
if "version = 19" not in db:
    raise SystemExit("Room schema 19 baseline not found")

payload = ''
diff_bytes = gzip.decompress(base64.b64decode(payload))
with tempfile.NamedTemporaryFile(prefix="phase1457-", suffix=".diff", delete=False) as tmp:
    tmp.write(diff_bytes)
    diff_path = tmp.name
subprocess.run(["patch", "-p2", "--forward", "--batch", "-i", diff_path], cwd=root, check=True)

checks = {
    "app/build.gradle.kts": ["versionCode = 46", "0.15.4.7-phase14.5-warehouse-reorder"],
    "app/src/main/java/com/fush/erp/data/FushDatabase.kt": ["WarehouseReorderPolicyEntity::class", "version = 20"],
    "app/src/main/java/com/fush/erp/data/Migrations.kt": ["MIGRATION_19_20", "warehouse_reorder_policies"],
    "app/src/main/java/com/fush/erp/data/dao/AdvancedInventoryDao.kt": ["observeReorderPolicies", "observeReorderAlerts(at: Long)", "reorderPolicyById"],
    "app/src/main/java/com/fush/erp/ui/screens/AdvancedInventoryScreens.kt": ["إعداد حدود إعادة الطلب حسب المخزن", "observeReorderAlerts(reorderAt)"],
    "app/src/test/java/com/fush/erp/domain/WarehouseReorderMathTest.kt": ["usableQuantity_excludesExpiredAndControlledLots"],
}
for rel, needles in checks.items():
    text = (root / rel).read_text(encoding="utf-8")
    for needle in needles:
        if needle not in text:
            raise SystemExit(f"Patch verification failed: {rel} missing {needle}")
print("Phase 14.5.7 warehouse-specific reorder patch applied successfully")
